"""Bahasa Indonesia — sirah (sira_001 … sira_150)."""

T = {
"sira_001": ("Di kota manakah Nabi Muhammad ﷺ dilahirkan?", ["Makkah", "Madinah", "Ta'if", "Yerusalem"], "Nabi Muhammad ﷺ lahir di Makkah, di wilayah Hijaz."),
"sira_002": ("Apa nama tahun kelahiran Nabi ﷺ, yang ditandai peristiwa gajah?", ["Tahun Gajah", "Tahun Kemenangan", "Tahun Unta", "Tahun Cahaya"], "Peristiwa gajah, saat Allah melindungi Ka'bah, dikisahkan dalam surah Al-Fil."),
"sira_003": ("Siapakah nama istri pertama Nabi ﷺ?", ["Khadijah", "Aisyah", "Hafshah", "Zainab"], "Khadijah binti Khuwailid adalah istri pertama Nabi ﷺ dan orang pertama yang beriman kepada risalahnya."),
"sira_004": ("Di gua manakah Nabi ﷺ menerima wahyu pertama?", ["Gua Hira", "Gua Tsur", "Gua Ashabul Kahfi", "Gua Uhud"], "Wahyu pertama turun di Gua Hira, di Jabal Nur dekat Makkah."),
"sira_005": ("Malaikat siapakah yang membawa wahyu kepada Nabi ﷺ?", ["Jibril", "Mikail", "Israfil", "Malik"], "Al-Qur'an menyebutkan dengan jelas bahwa Jibril membawa wahyu dengan izin Allah."),
"sira_006": ("Apa nama perpindahan Nabi ﷺ dan para sahabatnya dari Makkah ke Madinah?", ["Hijrah", "Isra", "Mi'raj", "Fathu Makkah"], "Hijrah adalah perpindahan bersejarah ke Madinah, titik awal kalender Islam."),
"sira_007": ("Ke kota manakah Nabi ﷺ dan Abu Bakar berhijrah?", ["Madinah", "Ta'if", "Damaskus", "Yerusalem"], "Nabi ﷺ dan Abu Bakar berhijrah dari Makkah ke Madinah (dahulu bernama Yatsrib)."),
"sira_008": ("Al-Qur'an menyebut seorang sahabat sebagai «yang kedua dari dua orang, ketika keduanya berada di gua» saat hijrah. Siapakah dia?", ["Abu Bakar", "Umar", "Utsman", "Ali"], "Al-Qur'an merujuk kepada Abu Bakar, yang menemani Nabi ﷺ di Gua Tsur saat hijrah."),
"sira_009": ("Perang manakah, yang disebut dalam Al-Qur'an, ketika pasukan Muslim yang kecil mengalahkan pasukan yang jauh lebih besar?", ["Perang Badar", "Perang Uhud", "Perang Khandaq", "Perang Hunain"], "Di Badar, Allah memberi kemenangan kepada sekelompok kecil orang beriman atas pasukan yang jauh lebih besar."),
"sira_010": ("Apa nama kembalinya Nabi ﷺ dan para sahabat ke Makkah yang berlangsung damai?", ["Pembebasan Makkah (Fathu Makkah)", "Perang Makkah", "Pengepungan Makkah", "Jatuhnya Makkah"], "Pembebasan Makkah berlangsung sebagian besar secara damai, tanpa pertumpahan darah yang luas."),
"sira_011": ("Apa nama khutbah terakhir Nabi ﷺ menjelang akhir hayatnya?", ["Khutbah Perpisahan (Khutbatul Wada')", "Khutbah Makkah", "Khutbah Gua", "Khutbah Badar"], "Khutbah Perpisahan disampaikan saat haji terakhir Nabi ﷺ."),
"sira_012": ("Pada bulan apakah Al-Qur'an menyatakan wahyunya mulai diturunkan?", ["Ramadan", "Muharram", "Rajab", "Dzulhijjah"], "Al-Qur'an menyatakan bahwa Ramadan adalah bulan diturunkannya Al-Qur'an."),
"sira_013": ("Apa pekerjaan Nabi ﷺ sebelum menerima wahyu?", ["Pedagang", "Hanya penggembala", "Pandai besi", "Juru tulis"], "Nabi ﷺ berdagang, sebuah fakta yang mapan dalam biografinya."),
"sira_014": ("Kakek Nabi ﷺ yang manakah yang mengasuhnya setelah ibunya wafat?", ["Abdul Muthalib", "Abu Thalib", "Abu Lahab", "Abu Sufyan"], "Abdul Muthalib mengasuh Muhammad ﷺ kecil setelah wafatnya ibunya, Aminah."),
"sira_015": ("Paman manakah yang membesarkan Nabi ﷺ setelah kakeknya wafat?", ["Abu Thalib", "Al-Abbas", "Hamzah", "Abu Lahab"], "Abu Thalib mengambil tanggung jawab membesarkan keponakannya setelah Abdul Muthalib wafat."),
"sira_016": ("Apa nama perjalanan malam Nabi ﷺ dari Makkah ke Yerusalem yang disebut dalam Al-Qur'an?", ["Isra", "Hijrah", "Fathu Makkah", "Ghazwah"], "Surah Al-Isra dibuka dengan menggambarkan perjalanan malam yang ajaib ini."),
"sira_017": ("Putri Nabi ﷺ yang manakah yang menikah dengan Ali bin Abi Thalib?", ["Fathimah", "Zainab", "Ruqayyah", "Ummu Kultsum"], "Fathimah, putri Nabi ﷺ dan Khadijah, menikah dengan Ali bin Abi Thalib, fakta yang sangat mapan."),
"sira_018": ("Bulan apakah yang menandai awal tahun kalender Islam, merujuk pada hijrah?", ["Muharram", "Ramadan", "Syawal", "Dzulqa'dah"], "Kalender Islam dimulai dengan bulan Muharram, merujuk pada tahun hijrah."),
"sira_019": ("Siapakah muazin pertama dalam Islam, yang dipilih Nabi ﷺ untuk mengumandangkan azan?", ["Bilal bin Rabah", "Abu Bakar", "Umar bin Khattab", "Salman al-Farisi"], "Bilal, dengan suaranya yang indah, dipilih sebagai muazin pertama Islam."),
"sira_020": ("Masjid pertama apakah yang didirikan Nabi ﷺ saat tiba di dekat Madinah?", ["Masjid Quba", "Masjidil Haram", "Masjidil Aqsa", "Masjid Qiblatain"], "Setibanya di Quba, di gerbang Madinah, Nabi ﷺ mendirikan masjid pertama di sana."),
"sira_021": ("Siapakah nama ibu Nabi ﷺ?", ["Aminah", "Khadijah", "Halimah", "Fathimah"], "Aminah binti Wahb adalah ibu Nabi ﷺ; Halimah adalah ibu susunya."),
"sira_022": ("Siapakah nama ayah Nabi ﷺ, yang wafat sebelum kelahirannya?", ["Abdullah", "Abu Thalib", "Abdul Muthalib", "Hamzah"], "Abdullah bin Abdul Muthalib wafat sebelum putranya, Muhammad ﷺ, lahir."),
"sira_023": ("Julukan apakah yang diberikan penduduk Makkah kepada Nabi ﷺ sebelum kenabian, karena kejujurannya?", ["Al-Amin (yang terpercaya)", "Al-Faruq", "Ash-Shiddiq", "Saifullah"], "Bahkan sebelum kenabian ia disebut Al-Amin: orang-orang menitipkan harta mereka kepadanya."),
"sira_024": ("Pada tahun hijriah keberapa pembebasan Makkah terjadi?", ["Tahun ke-8", "Tahun ke-2", "Tahun ke-5", "Tahun ke-10"], "Pada tahun 8 H Nabi ﷺ memasuki Makkah nyaris tanpa pertempuran dan memaafkan penduduknya."),
"sira_025": ("Pada tahun hijriah keberapa Nabi ﷺ menunaikan Haji Wada'?", ["Tahun ke-10", "Tahun ke-6", "Tahun ke-8", "Tahun ke-12"], "Haji Wada' berlangsung pada tahun 10 H; Nabi ﷺ menyampaikan khutbah terakhirnya di sana."),
"sira_026": ("Berapa putri yang dimiliki Nabi ﷺ?", ["4", "1", "2", "7"], "Zainab, Ruqayyah, Ummu Kultsum dan Fathimah: empat putri Nabi ﷺ."),
"sira_027": ("Apa sebutan bagi penduduk Madinah yang menyambut dan menolong kaum Muslim yang berhijrah?", ["Anshar (para penolong)", "Muhajirin", "Quraisy", "Tabi'in"], "Kaum Anshar, «para penolong», berbagi rumah dan harta dengan saudara-saudara mereka yang berhijrah."),
"sira_028": ("Apa sebutan bagi kaum Muslim yang meninggalkan Makkah untuk berhijrah ke Madinah?", ["Muhajirin (orang-orang yang berhijrah)", "Anshar", "Hunafa'", "Ghuzat"], "Kaum Muhajirin meninggalkan rumah dan harta di Makkah demi menjaga iman mereka."),
"sira_029": ("Pada bulan apakah Perang Badar terjadi?", ["Ramadan", "Muharram", "Dzulhijjah", "Rajab"], "Perang Badar terjadi pada bulan Ramadan tahun 2 H."),
"sira_030": ("Sebelum kiblat ditetapkan ke Ka'bah, ke kota manakah kaum Muslim salat menghadap?", ["Yerusalem (Baitul Maqdis)", "Madinah", "Ta'if", "Damaskus"], "Kaum Muslim mula-mula salat menghadap Baitul Maqdis; lalu Allah memerintahkan menghadap Masjidil Haram (Al-Qur'an 2:142-144)."),
"sira_031": ("Dari suku manakah Nabi Muhammad ﷺ berasal?", ["Quraisy", "Aus", "Khazraj", "Tsaqif"], "Sebuah surah utuh dinamai dengan nama sukunya: Quraisy."),
"sira_032": ("Dari klan Quraisy manakah Nabi ﷺ berasal?", ["Bani Hasyim", "Bani Umayyah", "Bani Makhzum", "Bani Tamim"], "Nabi ﷺ berasal dari Bani Hasyim, klan buyutnya Hasyim."),
"sira_033": ("Siapakah nama ibu susu yang menyusui Nabi ﷺ di padang pasir?", ["Halimah as-Sa'diyah", "Aminah", "Khadijah", "Fathimah"], "Menurut adat Makkah, bayi itu dititipkan kepada ibu susu Badui: Halimah as-Sa'diyah."),
"sira_034": ("Paman Nabi ﷺ manakah, pahlawan Badar, yang gugur syahid di Uhud?", ["Hamzah", "Abu Thalib", "Al-Abbas", "Abu Lahab"], "Hamzah bin Abdul Muthalib berjuang di Badar dan gugur dalam Perang Uhud."),
"sira_035": ("Sepupu Nabi ﷺ manakah, yang dibesarkan di rumahnya, menjadi khalifah keempat?", ["Ali bin Abi Thalib", "Ja'far", "Aqil", "Al-Abbas"], "Ali, putra Abu Thalib, tumbuh bersama Nabi ﷺ dan menjadi khalifah keempat yang lurus."),
"sira_036": ("Siapakah khalifah pertama setelah wafatnya Nabi ﷺ?", ["Abu Bakar", "Umar", "Utsman", "Ali"], "Abu Bakar ash-Shiddiq dipilih sebagai khalifah pertama."),
"sira_037": ("Gelar apakah yang disandang Abu Bakar karena mempercayai Nabi ﷺ tanpa ragu?", ["Ash-Shiddiq (yang membenarkan)", "Al-Faruq", "Dzun-Nurain", "Saifullah"], "Abu Bakar disebut ash-Shiddiq, orang yang membenarkan dan mempercayai kebenaran."),
"sira_038": ("Gelar apakah yang disandang Umar bin Khattab?", ["Al-Faruq (pembeda antara benar dan salah)", "Ash-Shiddiq", "Dzun-Nurain", "Al-Amin"], "Umar disebut al-Faruq, yang memisahkan kebenaran dari kebatilan."),
"sira_039": ("Mengapa Utsman bin Affan disebut «Dzun-Nurain», pemilik dua cahaya?", ["Ia menikahi dua putri Nabi ﷺ secara berurutan", "Ia membawa dua lampu", "Ia menghafal Al-Qur'an dua kali", "Ia berhijrah dua kali"], "Utsman menikahi Ruqayyah dan, setelah wafatnya, Ummu Kultsum, keduanya putri Nabi ﷺ."),
"sira_040": ("Dalam urutan apakah keempat khalifah yang lurus saling menggantikan?", ["Abu Bakar, Umar, Utsman, Ali", "Ali, Umar, Abu Bakar, Utsman", "Umar, Abu Bakar, Ali, Utsman", "Abu Bakar, Ali, Umar, Utsman"], "Abu Bakar, lalu Umar, lalu Utsman, lalu Ali."),
"sira_041": ("Siapakah orang pertama yang beriman kepada risalah Nabi ﷺ?", ["Khadijah, istrinya", "Abu Bakar", "Ali", "Bilal"], "Khadijah beriman kepadanya sejak wahyu pertama dan mendukungnya."),
"sira_042": ("Siapakah yang membeli Bilal untuk membebaskannya dari siksaan tuannya?", ["Abu Bakar", "Umar", "Hamzah", "Utsman"], "Abu Bakar membeli Bilal dan memerdekakannya."),
"sira_043": ("Siapakah syahid pertama dalam Islam, yang dibunuh di Makkah karena imannya?", ["Sumayyah, ibu Ammar", "Asma", "Ummu Salamah", "Shafiyyah"], "Sumayyah binti Khayyath, ibu Ammar bin Yasir, dibunuh oleh Abu Jahal."),
"sira_044": ("Ke negeri manakah hijrah pertama kaum Muslim yang dianiaya di Makkah?", ["Habasyah (Etiopia)", "Persia", "Yaman", "Mesir"], "Para muhajir pertama pergi ke Habasyah, kepada seorang raja yang adil."),
"sira_045": ("Siapakah nama raja Habasyah yang melindungi kaum Muslim, dan yang disalatkan Nabi ﷺ secara gaib?", ["An-Najasyi (Negus)", "Heraklius", "Kisra", "Al-Muqauqis"], "Nabi ﷺ mengabarkan wafatnya Najasyi pada hari itu juga dan menyalatkannya bersama para sahabat."),
"sira_046": ("Sahabat manakah yang berbicara di hadapan Najasyi untuk menjelaskan Islam?", ["Ja'far bin Abi Thalib", "Utsman", "Bilal", "Mush'ab bin Umair"], "Ja'far menjelaskan kepada raja apa yang diajarkan Nabi ﷺ dan membacakan ayat-ayat surah Maryam."),
"sira_047": ("Paman Nabi ﷺ manakah yang dikecam namanya dalam Al-Qur'an?", ["Abu Lahab", "Abu Thalib", "Al-Abbas", "Hamzah"], "«Binasalah kedua tangan Abu Lahab dan binasalah dia!»"),
"sira_048": ("Apa nama tahun ketika Nabi ﷺ kehilangan istrinya Khadijah dan pamannya Abu Thalib?", ["Tahun Kesedihan ('Amul Huzn)", "Tahun Gajah", "Tahun Delegasi", "Tahun Kelaparan"], "Dua penopang besar Nabi ﷺ wafat pada tahun yang sama, yang dikenal sebagai Tahun Kesedihan."),
"sira_049": ("Di kota manakah Nabi ﷺ diusir dan dilukai setelah berdakwah, sebelum ia menolak malaikat gunung menghancurkan penduduknya?", ["Ta'if", "Madinah", "Khaibar", "Tabuk"], "Ditolak di Ta'if, ia menolak membinasakan penduduknya, berharap keturunan mereka akan menyembah Allah."),
"sira_050": ("Selama Isra dan Mi'raj, kewajiban apakah yang ditetapkan bagi kaum Muslim?", ["Salat lima waktu", "Puasa Ramadan", "Zakat", "Haji"], "Salat diwajibkan pada malam itu, dikurangi dari lima puluh menjadi lima, dengan pahala lima puluh."),
"sira_051": ("Pohon apakah, di batas terjauh, yang dilihat Nabi ﷺ saat Mi'raj, menurut surah An-Najm?", ["Sidratul Muntaha", "Pohon zaitun yang diberkahi", "Pohon kurma Maryam", "Pohon Thuba"], "«Di dekat Sidratul Muntaha», pohon bidara di batas terjauh."),
"sira_052": ("Apa nama baiat yang diberikan penduduk Yatsrib kepada Nabi ﷺ sebelum hijrah?", ["Baiat Aqabah", "Perjanjian Hudaibiyah", "Baiat di bawah pohon", "Piagam Madinah"], "Penduduk Yatsrib berbaiat kepada Nabi ﷺ di Aqabah, dekat Mina, sebelum hijrah."),
"sira_053": ("Sahabat manakah yang diutus Nabi ﷺ ke Yatsrib, sebelum hijrah, untuk mengajarkan Islam?", ["Mush'ab bin Umair", "Bilal", "Abu Hurairah", "Khalid bin Walid"], "Mush'ab bin Umair adalah utusan pertama ke Yatsrib, mengajarkan Al-Qur'an kepada kaum Muslim baru."),
"sira_054": ("Siapakah yang tidur di ranjang Nabi ﷺ pada malam ia berangkat hijrah?", ["Ali bin Abi Thalib", "Abu Bakar", "Zaid bin Haritsah", "Bilal"], "Ali menggantikan tempatnya di ranjang untuk mengecoh para pengintai, lalu mengembalikan titipan kepada penduduk Makkah."),
"sira_055": ("Di gua manakah Nabi ﷺ dan Abu Bakar bersembunyi saat hijrah?", ["Gua Tsur", "Gua Hira", "Gua Uhud", "Gua Ta'if"], "Mereka bersembunyi tiga hari di Gua Tsur, di selatan Makkah."),
"sira_056": ("Putri Abu Bakar manakah yang membawa bekal ke gua dan dijuluki «pemilik dua ikat pinggang»?", ["Asma", "Aisyah", "Ummu Kultsum", "Ummu Ruman"], "Asma merobek ikat pinggangnya menjadi dua untuk mengikat bekal: maka dijuluki «Dzatun Nithaqain»."),
"sira_057": ("Apa yang terjadi pada Suraqah, yang mengejar Nabi ﷺ saat hijrah?", ["Kudanya terperosok ke dalam tanah, dan ia meminta jaminan keamanan", "Ia menyusul Nabi ﷺ", "Ia tersesat di gurun", "Ia jatuh sakit"], "Kaki kudanya terperosok ke tanah; Suraqah meminta jaminan keamanan dan pergi tanpa berbuat jahat."),
"sira_058": ("Apa nama lama Madinah yang disebut dalam Al-Qur'an?", ["Yatsrib", "Thaibah", "Khaibar", "Bakkah"], "«Wahai penduduk Yatsrib…», kata Al-Qur'an, mengenang Perang Ahzab."),
"sira_059": ("Siapakah nama unta Nabi ﷺ yang menderum di Hudaibiyah?", ["Al-Qashwa", "Al-Buraq", "Ad-Duldul", "Al-Adhba"], "Di Hudaibiyah, Al-Qashwa menderum; Nabi ﷺ bersabda: «Yang menahan gajah telah menahannya.»"),
"sira_060": ("Apa yang Nabi ﷺ tetapkan antara Muhajirin dan Anshar setibanya di Madinah?", ["Persaudaraan, berpasang-pasangan", "Pajak", "Pasukan", "Pasar"], "Ia mempersaudarakan kaum Muhajirin dengan Anshar, setiap Muhajir dengan seorang saudara dari Anshar."),
"sira_061": ("Apa nama dokumen yang digunakan Nabi ﷺ untuk mengatur hubungan antar komunitas di Madinah?", ["Piagam (Shahifah) Madinah", "Perjanjian Hudaibiyah", "Perjanjian Ta'if", "Piagam Quba"], "Shahifah menetapkan hak dan kewajiban kaum Muslim serta suku-suku lain di Madinah."),
"sira_062": ("Apa sebutan bagi para sahabat miskin yang tinggal di masjid Nabi ﷺ?", ["Ahlus Shuffah (penghuni serambi)", "Muhajirin", "Anshar", "Hawariyyun"], "Abu Hurairah menceritakan bahwa ia termasuk Ahlus Shuffah, yang diberi makan oleh Nabi ﷺ."),
"sira_063": ("Berapa tahun setelah hijrah Perang Badar terjadi?", ["Dua", "Lima", "Delapan", "Sepuluh"], "Badar terjadi pada tahun 2 H, di bulan Ramadan."),
"sira_064": ("Berapa malaikat yang Allah janjikan sebagai bala bantuan bagi orang beriman di Badar?", ["Seribu", "Seratus", "Sepuluh", "Seratus ribu"], "«Aku akan mendatangkan bala bantuan kepadamu dengan seribu malaikat yang datang berturut-turut.»"),
"sira_065": ("Di Uhud, kesalahan pasukan pemanah manakah yang membalikkan jalannya perang?", ["Mereka meninggalkan bukit meski Nabi ﷺ memerintahkan sebaliknya", "Mereka menembak terlalu dini", "Mereka tertidur", "Mereka berpindah pihak"], "Nabi ﷺ memerintahkan pemanah tidak bergerak; sebagian besar turun untuk mengambil rampasan, dan pasukan berkuda musuh memutar."),
"sira_066": ("Dekat kota manakah Gunung Uhud berada?", ["Madinah", "Makkah", "Ta'if", "Yerusalem"], "Gunung Uhud terletak di utara Madinah; pertempuran terjadi di kakinya."),
"sira_067": ("Sahabat manakah yang mengusulkan menggali parit untuk mempertahankan Madinah dari pasukan sekutu?", ["Salman al-Farisi", "Bilal", "Abu Dzar", "Shuhaib"], "Salman al-Farisi mengusulkan parit, taktik yang dikenal di Persia."),
"sira_068": ("Dengan nama apa lagi Perang Khandaq dikenal, menurut surah yang membicarakannya?", ["Perang Ahzab (pasukan sekutu)", "Perang Badar", "Perang Hunain", "Perang Mu'tah"], "Surah Al-Ahzab mengenang pasukan sekutu yang mengepung Madinah dan angin yang dikirim melawan mereka."),
"sira_069": ("Apa nama baiat di bawah pohon di Hudaibiyah, yang Allah nyatakan Dia ridha dengannya?", ["Baiat Ridhwan", "Baiat Aqabah", "Baiat Nisa", "Baiat Fath"], "«Sungguh Allah telah meridhai orang-orang mukmin ketika mereka berbaiat kepadamu di bawah pohon.»"),
"sira_070": ("Surah manakah yang dibuka dengan «Sungguh, Kami telah memberimu kemenangan yang nyata», diturunkan setelah Perjanjian Hudaibiyah?", ["Al-Fath", "An-Nasr", "Al-Anfal", "At-Taubah"], "«Sungguh, Kami telah memberimu kemenangan yang nyata»: surah Al-Fath."),
"sira_071": ("Pada tahun hijriah keberapa Perjanjian Hudaibiyah disepakati?", ["Tahun ke-6", "Tahun ke-2", "Tahun ke-8", "Tahun ke-10"], "Perjanjian Hudaibiyah disepakati pada tahun 6 H antara kaum Muslim dan Quraisy."),
"sira_072": ("Kaisar Bizantium manakah yang menerima surat Nabi ﷺ yang mengajaknya masuk Islam dan menanyai Abu Sufyan tentangnya?", ["Heraklius", "Nero", "Konstantin", "Yustinianus"], "Heraklius menanyai Abu Sufyan tentang Nabi ﷺ setelah menerima suratnya."),
"sira_073": ("Kepada siapakah Nabi ﷺ menyerahkan panji di Khaibar, setelah bersabda: «Besok aku akan memberikannya kepada seorang yang dicintai Allah dan Rasul-Nya»?", ["Ali bin Abi Thalib", "Abu Bakar", "Umar", "Sa'd bin Abi Waqqash"], "Ia memanggil Ali yang sakit mata; ia mengusapkan ludahnya, menyembuhkannya, dan memberinya panji."),
"sira_074": ("Tiga panglima manakah yang gugur berturut-turut dalam Perang Mu'tah?", ["Zaid bin Haritsah, Ja'far bin Abi Thalib dan Abdullah bin Rawahah", "Hamzah, Mush'ab dan Sa'd", "Abu Bakar, Umar dan Utsman", "Bilal, Salman dan Shuhaib"], "Nabi ﷺ mengumumkan di Madinah: «Zaid mengambil panji lalu gugur, lalu Ja'far, lalu Ibnu Rawahah… lalu sebilah pedang Allah mengambilnya.»"),
"sira_075": ("Sahabat manakah yang disebut Nabi ﷺ «sebilah pedang di antara pedang-pedang Allah»?", ["Khalid bin Walid", "Ali", "Hamzah", "Abu Ubaidah"], "Di Mu'tah, «sebilah pedang di antara pedang-pedang Allah», Khalid bin Walid, mengambil panji dan menyelamatkan pasukan."),
"sira_076": ("Apa yang Nabi ﷺ lakukan terhadap berhala-berhala di sekitar Ka'bah saat pembebasan Makkah?", ["Ia merobohkannya sambil membaca «Kebenaran telah datang dan kebatilan telah lenyap»", "Ia menjualnya", "Ia membawanya ke Madinah", "Ia membiarkannya"], "Ia memukul berhala-berhala dengan tongkatnya seraya berkata: «Kebenaran telah datang dan kebatilan telah lenyap.»"),
"sira_077": ("Siapakah yang mengumandangkan azan dari atas Ka'bah pada hari pembebasan Makkah?", ["Bilal", "Abu Bakar", "Ali", "Umar"], "Nabi ﷺ memerintahkan Bilal naik ke atas Ka'bah dan mengumandangkan azan."),
"sira_078": ("Apa yang Nabi ﷺ katakan kepada penduduk Makkah yang kalah dan pernah menganiayanya, pada hari pembebasan?", ["«Pergilah, kalian bebas»", "«Kalian akan diadili besok»", "«Tinggalkan kota ini»", "«Bayarlah tebusan»"], "Ia memaafkan mereka: «Pergilah, kalian bebas.»"),
"sira_079": ("Dalam perang manakah, yang disebut dalam Al-Qur'an, kaum Muslim awalnya terkejut meski berjumlah besar?", ["Hunain", "Badar", "Uhud", "Khaibar"], "«Pada hari Hunain, jumlahmu yang banyak membuatmu bangga, tetapi itu tidak berguna bagimu.»"),
"sira_080": ("Sahabat manakah yang tidak ikut ekspedisi Tabuk, mengaku dengan jujur, dan diampuni melalui wahyu?", ["Ka'b bin Malik", "Abu Dzar", "Anas bin Malik", "Abu Hurairah"], "Ka'b bin Malik berkata jujur, menanggung lima puluh hari pengucilan, lalu Allah menurunkan ampunan baginya (9:118)."),
"sira_081": ("Apa nama tahun 9 H, ketika banyak suku datang ke Madinah untuk memeluk Islam?", ["Tahun Delegasi ('Amul Wufud)", "Tahun Kesedihan", "Tahun Gajah", "Tahun Kekeringan"], "Setelah pembebasan Makkah, delegasi suku-suku Arab berdatangan ke Madinah."),
"sira_082": ("Di manakah Nabi ﷺ menyampaikan Khutbah Perpisahan?", ["Di Arafah", "Di Madinah", "Di Gunung Uhud", "Di Ta'if"], "Khutbah Perpisahan disampaikan di Arafah, saat Haji Wada'."),
"sira_083": ("Ayat manakah, yang diturunkan saat Haji Wada', mengumumkan bahwa agama telah disempurnakan?", ["«Pada hari ini telah Aku sempurnakan agamamu bagimu»", "«Bacalah dengan nama Tuhanmu»", "«Apabila telah datang pertolongan Allah»", "«Katakanlah: Dialah Allah Yang Maha Esa»"], "«Pada hari ini telah Aku sempurnakan agamamu bagimu, dan telah Aku cukupkan nikmat-Ku kepadamu.»"),
"sira_084": ("Di kota manakah Nabi ﷺ wafat dan dimakamkan?", ["Madinah", "Makkah", "Yerusalem", "Ta'if"], "Beliau wafat di Madinah pada tahun 11 H dan dimakamkan di sana."),
"sira_085": ("Di kamar istri manakah Nabi ﷺ dimakamkan?", ["Aisyah", "Khadijah", "Hafshah", "Ummu Salamah"], "Beliau dimakamkan di tempat wafatnya, di kamar Aisyah, yang kini berada di dalam Masjid Nabawi."),
"sira_086": ("Siapakah yang menyatakan, saat wafatnya Nabi ﷺ: «Barang siapa menyembah Muhammad, Muhammad telah wafat; barang siapa menyembah Allah, Allah Mahahidup»?", ["Abu Bakar", "Umar", "Ali", "Bilal"], "Abu Bakar menenangkan para sahabat dan membaca: «Muhammad hanyalah seorang rasul…» (3:144)."),
"sira_087": ("Siapakah nama kedua cucu Nabi ﷺ, putra Fathimah dan Ali?", ["Al-Hasan dan Al-Husain", "Ibrahim dan Isma'il", "Zaid dan Usamah", "Ja'far dan Aqil"], "Al-Hasan dan Al-Husain, yang sangat dicintai Nabi ﷺ."),
"sira_088": ("Istri Nabi ﷺ manakah yang merupakan putri Abu Bakar?", ["Aisyah", "Hafshah", "Zainab", "Saudah"], "Aisyah, putri Abu Bakar, meriwayatkan sangat banyak hadis."),
"sira_089": ("Istri Nabi ﷺ manakah yang merupakan putri Umar bin Khattab?", ["Hafshah", "Aisyah", "Ummu Habibah", "Maimunah"], "Hafshah binti Umar; naskah pertama Al-Qur'an yang dikumpulkan disimpan padanya."),
"sira_090": ("Sahabat manakah yang meriwayatkan hadis Nabi ﷺ paling banyak?", ["Abu Hurairah", "Anas bin Malik", "Abdullah bin Umar", "Jabir"], "Abu Hurairah, yang selalu mendampingi Nabi ﷺ, adalah sahabat yang paling banyak meriwayatkan hadis."),
"sira_091": ("Sahabat muda manakah yang melayani Nabi ﷺ selama sepuluh tahun tanpa pernah mendengar teguran?", ["Anas bin Malik", "Usamah bin Zaid", "Ibnu Abbas", "Zaid bin Tsabit"], "Anas berkata: «Aku melayani Nabi ﷺ sepuluh tahun; beliau tidak pernah berkata ‘ah’ kepadaku, atau ‘mengapa kau lakukan itu?’»"),
"sira_092": ("Untuk sepupu muda manakah Nabi ﷺ berdoa: «Ya Allah, ajarkanlah kepadanya Kitab»?", ["Abdullah bin Abbas", "Ali", "Ja'far", "Usamah"], "Nabi ﷺ memeluk Ibnu Abbas dan berdoa: «Ya Allah, ajarkanlah kepadanya Kitab.»"),
"sira_093": ("Sahabat manakah yang diutus Nabi ﷺ ke Yaman dengan pesan agar lebih dulu mengajak kepada tauhid?", ["Mu'adz bin Jabal", "Bilal", "Abu Musa saja", "Zaid bin Haritsah"], "«Engkau akan mendatangi kaum Ahli Kitab: ajaklah mereka lebih dulu bersaksi bahwa tidak ada tuhan selain Allah…»"),
"sira_094": ("Sahabat manakah yang disebut Nabi ﷺ «orang kepercayaan (amin) umat ini»?", ["Abu Ubaidah bin al-Jarrah", "Abu Bakar", "Utsman", "Khalid"], "«Setiap umat memiliki orang kepercayaan, dan orang kepercayaan umat ini adalah Abu Ubaidah bin al-Jarrah.»"),
"sira_095": ("Sahabat manakah, seorang penulis wahyu, yang ditugaskan Abu Bakar mengumpulkan Al-Qur'an?", ["Zaid bin Tsabit", "Abu Hurairah", "Anas bin Malik", "Salman"], "Setelah Perang Yamamah, Abu Bakar menugaskan Zaid bin Tsabit mengumpulkan Al-Qur'an."),
"sira_096": ("Pada masa khalifah manakah salinan resmi Al-Qur'an dikirim ke wilayah-wilayah?", ["Utsman bin Affan", "Abu Bakar", "Umar", "Ali"], "Utsman menyalin mushaf dan mengirim satu salinan ke setiap wilayah."),
"sira_097": ("Dari negeri manakah sahabat Salman, yang dijuluki «al-Farisi», berasal?", ["Persia", "Habasyah", "Bizantium", "Yaman"], "Salman al-Farisi, «orang Persia», datang dari Persia untuk mencari kebenaran."),
"sira_098": ("Sahabat manakah, yang berasal dari negeri Bizantium, dijuluki «ar-Rumi»?", ["Shuhaib", "Bilal", "Salman", "Abu Dzar"], "Shuhaib ar-Rumi tumbuh di kalangan Bizantium sebelum memeluk Islam di Makkah."),
"sira_099": ("Apa nama masjid Nabi ﷺ di Madinah?", ["Masjid Nabawi", "Masjidil Haram", "Masjidil Aqsa", "Masjid Quba"], "Masjid yang didirikannya di Madinah disebut Masjid Nabi, Masjid Nabawi."),
"sira_100": ("Berapa kali nama «Muhammad» muncul dalam Al-Qur'an?", ["Empat kali", "Satu kali", "Dua belas kali", "Seratus kali"], "Dalam ayat 3:144, 33:40, 47:2 dan 48:29; nama «Ahmad» muncul dalam 61:6."),
"sira_101": ("Bagaimana Al-Qur'an menggambarkan Nabi ﷺ bagi orang-orang beriman, dalam ayat 33:21?", ["Teladan yang baik", "Hakim yang keras", "Raja", "Penyair"], "«Sungguh, telah ada pada diri Rasulullah suri teladan yang baik bagimu.»"),
"sira_102": ("Apa kunyah (julukan kebapakan) Nabi ﷺ?", ["Abul Qasim", "Abu Bakar", "Abu Abdullah", "Abu Thalib"], "Beliau dipanggil Abul Qasim, mengikuti nama putra sulungnya Al-Qasim."),
"sira_103": ("Siapakah nama putra Nabi ﷺ yang lahir di Madinah dan wafat saat masih kecil?", ["Ibrahim", "Al-Qasim", "Abdullah", "Al-Hasan"], "Ibrahim, lahir di Madinah, wafat saat bayi; Nabi ﷺ menangis dan bersabda bahwa hati bersedih tanpa mengucapkan yang dimurkai Allah."),
"sira_104": ("Untuk siapakah Nabi ﷺ memimpin kafilah dagang ke Syam sebelum kenabian?", ["Khadijah", "Abu Bakar", "Abu Sufyan", "Al-Abbas"], "Khadijah, saudagar kaya, mempercayakan kafilahnya ke Syam kepada beliau, lalu melamarnya."),
"sira_105": ("Bagaimana Muhammad ﷺ muda menyelesaikan perselisihan klan tentang peletakan kembali Hajar Aswad?", ["Ia meletakkannya di atas kain yang diangkat setiap klan, lalu memasangnya sendiri", "Ia membawanya sendirian", "Ia mengundi", "Ia menyerahkannya kepada Abu Bakar"], "Ia membentangkan kain, meletakkan batu di atasnya, meminta para pemimpin klan mengangkat kain bersama, lalu memasangnya dengan tangannya sendiri."),
"sira_106": ("Pada usia berapa Nabi ﷺ menerima wahyu pertama?", ["Empat puluh tahun", "Dua puluh lima", "Lima puluh", "Enam puluh"], "Wahyu dimulai saat beliau berusia empat puluh tahun, di Gua Hira."),
"sira_107": ("Kepada sepupu Khadijah manakah, yang menguasai Kitab suci, Nabi ﷺ dibawa setelah wahyu pertama?", ["Waraqah bin Naufal", "Abu Thalib", "Abu Lahab", "Al-Walid"], "Waraqah berkata: «Inilah Namus (malaikat) yang Allah utus kepada Musa.»"),
"sira_108": ("Ke bukit manakah Nabi ﷺ naik untuk menyeru Quraisy secara terbuka, setelah ayat «Berilah peringatan kepada kerabat terdekatmu»?", ["Shafa", "Uhud", "Arafah", "Hira"], "Beliau naik ke Shafa, memanggil klan-klan Quraisy dan memperingatkan mereka akan azab yang keras."),
"sira_109": ("Khalifah manakah yang menetapkan kalender Islam dimulai dari tahun hijrah?", ["Umar bin Khattab", "Abu Bakar", "Utsman", "Ali"], "Pada masa Umar, hijrah dipilih sebagai titik awal kalender."),
"sira_110": ("Berapa tahun Nabi ﷺ tinggal di Madinah setelah hijrah?", ["Sepuluh", "Tiga", "Dua puluh", "Tiga belas"], "Beliau tinggal sepuluh tahun di Madinah, dari hijrah hingga wafatnya pada tahun 11 H."),
"sira_111": ("Berapa tahun Nabi ﷺ berdakwah di Makkah sebelum hijrah?", ["Tiga belas", "Tiga", "Sepuluh", "Dua puluh tiga"], "Tiga belas tahun di Makkah, lalu sepuluh di Madinah: dua puluh tiga tahun kenabian."),
"sira_112": ("Sahabat penyair manakah yang membela Nabi ﷺ dengan syairnya, dan untuknya beliau memohon dukungan Jibril?", ["Hassan bin Tsabit", "Ka'b bin Malik", "Abdullah bin Rawahah", "Labid"], "Nabi ﷺ berkata kepada Hassan: «Balaslah mereka, dan Jibril bersamamu.»"),
"sira_113": ("Tentang sahabat manakah Nabi ﷺ bersabda bahwa ia dianugerahi «salah satu seruling keluarga Dawud» karena bacaannya yang indah?", ["Abu Musa al-Asy'ari", "Bilal", "Ubay bin Ka'b", "Ibnu Mas'ud"], "Mendengar bacaannya, Nabi ﷺ bersabda bahwa Abu Musa dianugerahi salah satu seruling keluarga Dawud."),
"sira_114": ("Nabi ﷺ menganjurkan belajar Al-Qur'an dari empat sahabat. Siapakah di antara ini yang termasuk?", ["Abdullah bin Mas'ud", "Abu Hurairah", "Anas bin Malik", "Khalid bin Walid"], "«Pelajarilah Al-Qur'an dari empat orang: Ibnu Mas'ud, Salim, Mu'adz bin Jabal dan Ubay bin Ka'b.»"),
"sira_115": ("Dalam perang manakah Nabi ﷺ terluka di wajah dan kehilangan sebuah gigi?", ["Uhud", "Badar", "Hunain", "Khaibar"], "Di Uhud, gigi beliau patah dan wajahnya terluka."),
"sira_116": ("Kepada sahabat manakah, pemanah di Uhud, Nabi ﷺ bersabda: «Panahlah! Ayah dan ibuku sebagai tebusanmu»?", ["Sa'd bin Abi Waqqash", "Thalhah", "Az-Zubair", "Ali"], "Nabi ﷺ menyerahkan anak panah kepadanya seraya bersabda: «Panahlah, ayah dan ibuku sebagai tebusanmu.»"),
"sira_117": ("Kafilah manakah yang hendak dicegat kaum Muslim, yang berujung pada Perang Badar?", ["Kafilah Abu Sufyan yang kembali dari Syam", "Kafilah Najasyi", "Kafilah Persia", "Kafilah Ta'if"], "Kafilah Quraisy pimpinan Abu Sufyan lolos, tetapi pasukan Makkah datang ke Badar."),
"sira_118": ("Kapan pemimpin Makkah Abu Sufyan memeluk Islam?", ["Saat pembebasan Makkah", "Sebelum hijrah", "Di Badar", "Setelah wafatnya Nabi ﷺ"], "Abu Sufyan masuk Islam menjelang masuknya Nabi ﷺ ke Makkah."),
"sira_119": ("Mata air apakah yang memancar bagi Hajar dan putranya Isma'il di lembah Makkah?", ["Zamzam", "Nil", "Efrat", "Yordan"], "Seorang malaikat memukul tanah dan air Zamzam memancar; Hajar membuat kolam di sekelilingnya."),
"sira_120": ("Apa yang terukir pada cincin Nabi ﷺ?", ["«Muhammad Rasulullah»", "«Allahu Akbar»", "«La ilaha illallah»", "Hanya namanya"], "Cincin peraknya bertuliskan «Muhammad, Rasul Allah» dalam tiga baris."),
"sira_121": ("Makanan apakah yang disukai Nabi ﷺ, menurut Aisyah?", ["Makanan manis dan madu", "Ikan", "Rempah yang tajam", "Hanya cuka"], "Aisyah meriwayatkan bahwa Nabi ﷺ menyukai makanan manis dan madu."),
"sira_122": ("Pada hari apakah Nabi ﷺ dilahirkan, hari yang juga beliau gunakan untuk berpuasa?", ["Senin", "Jumat", "Sabtu", "Rabu"], "Ditanya tentang puasa Senin, beliau bersabda: «Itu hari aku dilahirkan dan hari wahyu turun kepadaku.»"),
"sira_123": ("Di manakah «cap kenabian» pada tubuh Nabi ﷺ?", ["Di antara kedua bahunya", "Di tangannya", "Di dahinya", "Di dadanya"], "Cap kenabian berada di antara kedua bahu beliau."),
"sira_124": ("Dari kayu apakah seorang tukang membuat mimbar Nabi ﷺ?", ["Kayu atsl (tamarisk)", "Kayu cedar", "Kayu zaitun", "Kayu kurma"], "Nabi ﷺ membuat mimbar dari kayu atsl, tempat beliau berbicara kepada orang-orang."),
"sira_125": ("Dua suku besar Madinah manakah yang membentuk kaum Anshar?", ["Aus dan Khazraj", "Quraisy dan Tsaqif", "Tamim dan Hawazin", "Kindah dan Hamdan"], "Aus dan Khazraj, yang lama bermusuhan, bersatu dalam Islam dan menjadi kaum Anshar."),
"sira_126": ("Gelar apakah yang Al-Qur'an berikan kepada istri-istri Nabi ﷺ?", ["Ibu orang-orang beriman (Ummahatul Mukminin)", "Ratu Madinah", "Putri Quraisy", "Penjaga Kitab"], "«Istri-istrinya adalah ibu mereka»: Ummahatul Mukminin."),
"sira_127": ("Pada tahun berapa Masehi hijrah terjadi?", ["622", "570", "632", "610"], "Hijrah pada tahun 622 menandai awal kalender Islam."),
"sira_128": ("Apa jawaban Abdurrahman bin Auf ketika saudara Anshar-nya menawarkan separuh hartanya?", ["«Tunjukkan saja pasar kepadaku»", "Ia menerima semuanya", "Ia meminta rumah", "Ia menolak berbicara"], "Ia berkata: «Semoga Allah memberkahi harta dan keluargamu; tunjukkan saja pasar kepadaku», dan ia makmur berdagang."),
"sira_129": ("Kepada sahabat manakah Nabi ﷺ bertanya ayat Al-Qur'an mana yang paling agung, lalu memujinya atas jawabannya (Ayat Kursi)?", ["Ubay bin Ka'b", "Abu Bakar", "Zaid bin Tsabit", "Bilal"], "Ubay menjawab: «Allah, tidak ada tuhan selain Dia, Yang Mahahidup…»; Nabi ﷺ bersabda: «Selamat atas ilmu itu, wahai Abul Mundzir!»"),
"sira_130": ("Bagaimana lokasi masjid Nabi ﷺ di Madinah dipilih?", ["Di tempat untanya menderum", "Dengan undian", "Di tengah pasar", "Di Gunung Uhud"], "Beliau membiarkan untanya berjalan bebas: di tempat unta itu menderum, masjid dibangun."),
"sira_131": ("Berapa putra Nabi ﷺ, yang semuanya wafat saat kecil?", ["Tiga", "Satu", "Lima", "Tidak ada"], "Al-Qasim dan Abdullah, dari Khadijah, serta Ibrahim, lahir di Madinah."),
"sira_132": ("Sahabat manakah, yang dimerdekakan Nabi ﷺ dan dibesarkan seperti anak, yang merupakan ayah Usamah?", ["Zaid bin Haritsah", "Bilal", "Salman", "Ammar"], "Zaid bin Haritsah, kesayangan Nabi ﷺ, adalah ayah Usamah bin Zaid."),
"sira_133": ("Sahabat muda manakah yang diangkat Nabi ﷺ memimpin pasukan menjelang wafatnya, meski masih muda?", ["Usamah bin Zaid", "Anas bin Malik", "Ibnu Abbas", "Ibnu Umar"], "Nabi ﷺ memberi Usamah kepemimpinan dan menjawab yang mengkritik usianya bahwa ia layak, seperti ayahnya."),
"sira_134": ("Kakek Nabi ﷺ manakah yang menggali kembali sumur Zamzam yang lama tertimbun?", ["Abdul Muthalib", "Hasyim", "Abdu Manaf", "Qushay"], "Abdul Muthalib menggali kembali Zamzam dan mengurusnya untuk para jamaah."),
"sira_135": ("Kira-kira berapa orang yang menyertai Nabi ﷺ dalam Perang Badar?", ["Sedikit di atas tiga ratus", "Sepuluh ribu", "Seribu", "Lima puluh"], "Kaum Muslim di Badar berjumlah sedikit di atas tiga ratus, menghadapi pasukan yang jauh lebih besar."),
"sira_136": ("Pada bulan apakah dalam kalender Islam Nabi ﷺ dilahirkan?", ["Rabi'ul Awwal", "Ramadan", "Muharram", "Dzulhijjah"], "Beliau lahir pada bulan Rabi'ul Awwal, di Tahun Gajah."),
"sira_137": ("Pada bulan apakah Nabi ﷺ tiba di Madinah saat hijrah?", ["Rabi'ul Awwal", "Ramadan", "Muharram", "Rajab"], "Beliau tiba di Madinah pada Rabi'ul Awwal, setelah singgah di Quba."),
"sira_138": ("Perjanjian apakah yang dibuat Quraisy untuk mengucilkan Bani Hasyim yang melindungi Nabi ﷺ?", ["Boikot: tidak berdagang dan tidak menikah dengan mereka", "Gencatan senjata sepuluh tahun", "Pembagian Ka'bah", "Persekutuan militer"], "Quraisy menandatangani perjanjian boikot, dan Bani Hasyim terkurung di sebuah lembah selama bertahun-tahun."),
"sira_139": ("Bagaimana Nabi ﷺ memulai dakwahnya di Makkah, sebelum seruan terbuka?", ["Dengan mengajak lingkaran terdekatnya secara diam-diam", "Dengan pasukan", "Dengan surat kepada raja-raja", "Dengan haji"], "Beliau lebih dulu mengajak kerabat dan sahabat secara tertutup, sebelum dakwah menjadi terbuka."),
"sira_140": ("Di antara dua bukit manakah Hajar berlari mencari air untuk Isma'il?", ["Shafa dan Marwah", "Uhud dan Tsur", "Arafah dan Mina", "Hira dan Tsur"], "Ia berlari tujuh kali antara Shafa dan Marwah: asal-usul sa'i para jamaah."),
"sira_141": ("Tentang cucu manakah Nabi ﷺ bersabda: «Putraku ini adalah sayyid; Allah akan mendamaikan dua kelompok Muslim melaluinya»?", ["Al-Hasan", "Al-Husain", "Usamah", "Ibnu Abbas"], "Al-Hasan bin Ali kelak mendamaikan dua kelompok besar kaum Muslim, sebagaimana diramalkan Nabi ﷺ."),
"sira_142": ("Siapakah nama putri Nabi ﷺ, ibu Al-Hasan dan Al-Husain?", ["Fathimah", "Zainab", "Ruqayyah", "Ummu Kultsum"], "Fathimah, istri Ali, adalah ibu Al-Hasan dan Al-Husain."),
"sira_143": ("Siapakah putri sulung Nabi ﷺ?", ["Zainab", "Fathimah", "Ruqayyah", "Ummu Kultsum"], "Zainab adalah yang tertua dari empat putri Nabi ﷺ."),
"sira_144": ("Sahabat manakah, mantan budak keturunan Habasyah, yang dipilih menjadi muazin karena suaranya yang indah?", ["Bilal bin Rabah", "Salman", "Shuhaib", "Zaid"], "Bilal, yang dimerdekakan Abu Bakar, menjadi muazin Nabi ﷺ."),
"sira_145": ("Tentang sahabat manakah Nabi ﷺ bersabda: «Seandainya aku mengambil seorang kekasih (khalil) di antara manusia, dialah orangnya»?", ["Abu Bakar", "Umar", "Ali", "Utsman"], "«Seandainya aku mengambil kekasih dari umatku, aku akan mengambil Abu Bakar, tetapi ia saudaraku dan sahabatku.»"),
"sira_146": ("Kota manakah, bersama Makkah, yang disebut «al-Haramain», dua tanah suci?", ["Madinah", "Yerusalem", "Ta'if", "Damaskus"], "Makkah dan Madinah adalah dua kota suci, al-Haramain."),
"sira_147": ("Berapa kali Nabi ﷺ menunaikan haji setelah hijrah?", ["Sekali, Haji Wada'", "Tiga kali", "Setiap tahun", "Tidak pernah"], "Beliau hanya berhaji sekali setelah hijrah: Haji Wada', pada tahun 10 H."),
"sira_148": ("Menurut Anas, apa yang Nabi ﷺ lakukan ketika seorang Badui menarik keras jubahnya sambil menuntut harta?", ["Beliau tersenyum dan memerintahkan agar ia diberi sesuatu", "Beliau menghukumnya", "Beliau pergi tanpa sepatah kata", "Beliau mengusirnya"], "Nabi ﷺ menoleh kepadanya, tertawa, dan memerintahkan agar ia diberi sesuatu."),
"sira_149": ("Kota manakah, tempat Masjidil Aqsa berada, yang menjadi tujuan Isra?", ["Yerusalem", "Damaskus", "Kairo", "Baghdad"], "Isra membawa Nabi ﷺ dari Makkah ke Masjidil Aqsa di Yerusalem."),
"sira_150": ("Berapa usia Nabi ﷺ ketika wafat?", ["Enam puluh tiga", "Empat puluh", "Lima puluh", "Delapan puluh"], "Beliau wafat pada usia enam puluh tiga tahun, pada tahun 11 H."),
}
